// ---------------------------------------------------------------------------
// Media object keys.
//
// Uploads always use `<gym>/<uuid>.<ext>`. Reads come from a public URL, so
// validating the key shape prevents path traversal (`../`), absolute paths and
// unexpected extensions from reaching the signed B2 request.
// ---------------------------------------------------------------------------

/** Extensions produced by `IMAGE_TYPES` in `worker/media.ts`. */
const MEDIA_EXTENSIONS = 'png|jpg|webp|gif|avif|svg';

/** `<safe-gym>/<uuid-v4>.<ext>` exactly as generated by `handleUpload`. */
export const MEDIA_KEY_RE = new RegExp(
  `^[A-Za-z0-9_-]{1,40}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\.(?:${MEDIA_EXTENSIONS})$`,
  'i',
);

export function isMediaKey(key: string): boolean {
  return MEDIA_KEY_RE.test(key);
}
